DO $seo$ DECLARE old_events jsonb;old_routes jsonb;deps jsonb;expected jsonb; BEGIN PERFORM set_config('lock_timeout','5s',true);
PERFORM 1 FROM tb_evento_corridas WHERE id_evento IN (45651) ORDER BY id_evento FOR UPDATE;
PERFORM 1 FROM tb_evento_corridas_percursos WHERE id_evento IN (45651) ORDER BY id_evento_percurso FOR UPDATE;
IF (SELECT count(*) FROM tb_evento_corridas_percursos WHERE id_evento IN (45651))<>2 THEN RAISE EXCEPTION 'Routes changed'; END IF;
SELECT jsonb_agg(to_jsonb(e) ORDER BY id_evento) INTO old_events FROM tb_evento_corridas e WHERE id_evento IN (45651);
SELECT jsonb_agg(to_jsonb(p) ORDER BY id_evento_percurso) INTO old_routes FROM tb_evento_corridas_percursos p WHERE id_evento IN (45651);
SELECT jsonb_build_object('tb_evento_percursos_gpx',(SELECT jsonb_build_object('count',count(*),'hash',md5(string_agg(md5(to_jsonb(d)::text),'' ORDER BY md5(to_jsonb(d)::text)))) FROM tb_evento_percursos_gpx d WHERE id_evento IN ('45651')),'tb_badges',(SELECT jsonb_build_object('count',count(*),'hash',md5(string_agg(md5(to_jsonb(d)::text),'' ORDER BY md5(to_jsonb(d)::text)))) FROM tb_badges d WHERE id_evento IN ('45651')),'tb_evento_corridas_relaciona',(SELECT jsonb_build_object('count',count(*),'hash',md5(string_agg(md5(to_jsonb(d)::text),'' ORDER BY md5(to_jsonb(d)::text)))) FROM tb_evento_corridas_relaciona d WHERE id_evento IN ('45651')),'tb_leaderboard_startlist_importacao',(SELECT jsonb_build_object('count',count(*),'hash',md5(string_agg(md5(to_jsonb(d)::text),'' ORDER BY md5(to_jsonb(d)::text)))) FROM tb_leaderboard_startlist_importacao d WHERE id_evento IN ('45651')),'tb_permit_atualiza',(SELECT jsonb_build_object('count',count(*),'hash',md5(string_agg(md5(to_jsonb(d)::text),'' ORDER BY md5(to_jsonb(d)::text)))) FROM tb_permit_atualiza d WHERE id_evento IN ('45651')),'tb_leaderboard_startlist',(SELECT jsonb_build_object('count',count(*),'hash',md5(string_agg(md5(to_jsonb(d)::text),'' ORDER BY md5(to_jsonb(d)::text)))) FROM tb_leaderboard_startlist d WHERE id_evento IN ('45651')),'tb_resultados_temp',(SELECT jsonb_build_object('count',count(*),'hash',md5(string_agg(md5(to_jsonb(d)::text),'' ORDER BY md5(to_jsonb(d)::text)))) FROM tb_resultados_temp d WHERE id_evento IN ('45651')),'tb_resultados',(SELECT jsonb_build_object('count',count(*),'hash',md5(string_agg(md5(to_jsonb(d)::text),'' ORDER BY md5(to_jsonb(d)::text)))) FROM tb_resultados d WHERE id_evento IN ('45651')),'tb_evento_saude_config',(SELECT jsonb_build_object('count',count(*),'hash',md5(string_agg(md5(to_jsonb(d)::text),'' ORDER BY md5(to_jsonb(d)::text)))) FROM tb_evento_saude_config d WHERE id_evento IN ('45651')),'tb_percurso_migracoes_strava',(SELECT jsonb_build_object('count',count(*),'hash',md5(string_agg(md5(to_jsonb(d)::text),'' ORDER BY md5(to_jsonb(d)::text)))) FROM tb_percurso_migracoes_strava d WHERE id_evento IN ('45651')),'tb_leaderboard_percurso',(SELECT jsonb_build_object('count',count(*),'hash',md5(string_agg(md5(to_jsonb(d)::text),'' ORDER BY md5(to_jsonb(d)::text)))) FROM tb_leaderboard_percurso d WHERE id_evento IN ('45651')),'tb_resultados_resumo',(SELECT jsonb_build_object('count',count(*),'hash',md5(string_agg(md5(to_jsonb(d)::text),'' ORDER BY md5(to_jsonb(d)::text)))) FROM tb_resultados_resumo d WHERE id_evento IN ('45651')),'tb_inscricoes',(SELECT jsonb_build_object('count',count(*),'hash',md5(string_agg(md5(to_jsonb(d)::text),'' ORDER BY md5(to_jsonb(d)::text)))) FROM tb_inscricoes d WHERE id_evento IN ('45651'))) INTO deps;
IF NOT EXISTS(SELECT 1 FROM tb_evento_corridas z WHERE id_evento=45651 AND md5(to_jsonb(z)::text)='0f279dbb136fa16f0d574eba080ff10c') THEN RAISE EXCEPTION 'Baseline drift'; END IF;
IF NOT EXISTS(SELECT 1 FROM tb_evento_corridas_percursos z WHERE id_evento_percurso=65055 AND md5(to_jsonb(z)::text)='c79d241dbd4c797065b16ef102bda9c1') THEN RAISE EXCEPTION 'Baseline drift'; END IF;
IF NOT EXISTS(SELECT 1 FROM tb_evento_corridas_percursos z WHERE id_evento_percurso=65056 AND md5(to_jsonb(z)::text)='4601895384f333a2af6546737a50339c') THEN RAISE EXCEPTION 'Baseline drift'; END IF;
UPDATE tb_evento_corridas SET cidade='Barra do Piraí',id_localidade=3006 WHERE id_evento=45651;
SELECT x || '{"cidade": "Barra do Piraí", "id_localidade": 3006}'::jsonb INTO expected FROM jsonb_array_elements(old_events) x WHERE (x->>'id_evento')::int=45651; IF (SELECT to_jsonb(e) FROM tb_evento_corridas e WHERE id_evento=45651) IS DISTINCT FROM expected THEN RAISE EXCEPTION 'Unexpected event fields'; END IF;
SELECT x || '{}'::jsonb INTO expected FROM jsonb_array_elements(old_routes) x WHERE (x->>'id_evento_percurso')::int=65055; IF (SELECT to_jsonb(p) FROM tb_evento_corridas_percursos p WHERE id_evento_percurso=65055) IS DISTINCT FROM expected THEN RAISE EXCEPTION 'Unexpected route fields'; END IF;
SELECT x || '{}'::jsonb INTO expected FROM jsonb_array_elements(old_routes) x WHERE (x->>'id_evento_percurso')::int=65056; IF (SELECT to_jsonb(p) FROM tb_evento_corridas_percursos p WHERE id_evento_percurso=65056) IS DISTINCT FROM expected THEN RAISE EXCEPTION 'Unexpected route fields'; END IF;
IF (SELECT count(*) FROM tb_evento_corridas_percursos WHERE id_evento IN (45651))<>2 THEN RAISE EXCEPTION 'Route IDs recreated'; END IF;
IF (SELECT jsonb_build_object('tb_evento_percursos_gpx',(SELECT jsonb_build_object('count',count(*),'hash',md5(string_agg(md5(to_jsonb(d)::text),'' ORDER BY md5(to_jsonb(d)::text)))) FROM tb_evento_percursos_gpx d WHERE id_evento IN ('45651')),'tb_badges',(SELECT jsonb_build_object('count',count(*),'hash',md5(string_agg(md5(to_jsonb(d)::text),'' ORDER BY md5(to_jsonb(d)::text)))) FROM tb_badges d WHERE id_evento IN ('45651')),'tb_evento_corridas_relaciona',(SELECT jsonb_build_object('count',count(*),'hash',md5(string_agg(md5(to_jsonb(d)::text),'' ORDER BY md5(to_jsonb(d)::text)))) FROM tb_evento_corridas_relaciona d WHERE id_evento IN ('45651')),'tb_leaderboard_startlist_importacao',(SELECT jsonb_build_object('count',count(*),'hash',md5(string_agg(md5(to_jsonb(d)::text),'' ORDER BY md5(to_jsonb(d)::text)))) FROM tb_leaderboard_startlist_importacao d WHERE id_evento IN ('45651')),'tb_permit_atualiza',(SELECT jsonb_build_object('count',count(*),'hash',md5(string_agg(md5(to_jsonb(d)::text),'' ORDER BY md5(to_jsonb(d)::text)))) FROM tb_permit_atualiza d WHERE id_evento IN ('45651')),'tb_leaderboard_startlist',(SELECT jsonb_build_object('count',count(*),'hash',md5(string_agg(md5(to_jsonb(d)::text),'' ORDER BY md5(to_jsonb(d)::text)))) FROM tb_leaderboard_startlist d WHERE id_evento IN ('45651')),'tb_resultados_temp',(SELECT jsonb_build_object('count',count(*),'hash',md5(string_agg(md5(to_jsonb(d)::text),'' ORDER BY md5(to_jsonb(d)::text)))) FROM tb_resultados_temp d WHERE id_evento IN ('45651')),'tb_resultados',(SELECT jsonb_build_object('count',count(*),'hash',md5(string_agg(md5(to_jsonb(d)::text),'' ORDER BY md5(to_jsonb(d)::text)))) FROM tb_resultados d WHERE id_evento IN ('45651')),'tb_evento_saude_config',(SELECT jsonb_build_object('count',count(*),'hash',md5(string_agg(md5(to_jsonb(d)::text),'' ORDER BY md5(to_jsonb(d)::text)))) FROM tb_evento_saude_config d WHERE id_evento IN ('45651')),'tb_percurso_migracoes_strava',(SELECT jsonb_build_object('count',count(*),'hash',md5(string_agg(md5(to_jsonb(d)::text),'' ORDER BY md5(to_jsonb(d)::text)))) FROM tb_percurso_migracoes_strava d WHERE id_evento IN ('45651')),'tb_leaderboard_percurso',(SELECT jsonb_build_object('count',count(*),'hash',md5(string_agg(md5(to_jsonb(d)::text),'' ORDER BY md5(to_jsonb(d)::text)))) FROM tb_leaderboard_percurso d WHERE id_evento IN ('45651')),'tb_resultados_resumo',(SELECT jsonb_build_object('count',count(*),'hash',md5(string_agg(md5(to_jsonb(d)::text),'' ORDER BY md5(to_jsonb(d)::text)))) FROM tb_resultados_resumo d WHERE id_evento IN ('45651')),'tb_inscricoes',(SELECT jsonb_build_object('count',count(*),'hash',md5(string_agg(md5(to_jsonb(d)::text),'' ORDER BY md5(to_jsonb(d)::text)))) FROM tb_inscricoes d WHERE id_evento IN ('45651')))) IS DISTINCT FROM deps THEN RAISE EXCEPTION 'Dependencies changed'; END IF; END $seo$